"""Generate the reference and Go layout constants from the checked source JSON."""
import json, re
raise SystemExit('V2 generator is historical and disabled. Use tools/generate_v3_map.py for active V3.')
from pathlib import Path
root=Path(__file__).resolve().parents[1]
s=json.loads((root/'protocols/north-v2.json').read_text(encoding='utf-8'))
def field(name, offset, words=1, type='uint16', unit=''):
    return dict(name=name, offset=offset, words=words, type=type, unit=unit)
# Extra layouts stay in source JSON after the first generation. No overwrite of
# manually maintained existing definitions.
defaults={
 'device_fields':[field('software_major',0),field('software_minor',1),field('map_version',2),field('capacity',3),field('bound_slots',4),field('enabled_slots',5),field('boot_id',6,4,'uint64'),field('utc_ms',10,4,'uint64'),field('config_revision',14,2,'uint32'),field('uptime_sec',16,2,'uint32'),field('clock_trusted',18),field('simulate',19),field('storage_error',20),field('tcp_enabled',21),field('reserved',22,42)],
 'port_fields':[field('physical_port',0),field('role_0_disabled_1_south_2_north',1),field('baud',2,2,'uint32'),field('parity_ascii',4),field('stop_bits',5),field('unit_id',6),field('enabled_meters',7),field('transactions',8,2,'uint32'),field('failures',10,2,'uint32'),field('cycle_ms',12,2,'uint32'),field('queue_depth',14),field('channel_error',15),field('reserved',16,16)],
 'detail_fields':[field('raw_IR0_52',0,53),field('reserved',53),field('binding_version',54,2,'uint32'),field('sequence',56,2,'uint32'),field('known_bitmap_IR0_bit15',58,4,'bits'),field('reserved2',62,2),field('group_metadata_6x12',64,72),field('reserved3',136,8)],
 'group_metadata_fields':[field('status_bits_read_error_unsupported_timeTrusted',0,1,'bits'),field('failure_count_saturating',1),field('sequence',2,2,'uint32'),field('utc_ms',4,4,'uint64'),field('monotonic_age_ms',8,2,'uint32'),field('source_count',10),field('source_start',11)],
 'parameter_fields':[field('HR0',0),field('HR130_132',1,3),field('HR3300_3337',4,38),field('snapshot_utc_ms',42,4,'uint64'),field('snapshot_valid',46),field('snapshot_error',47)],
 'command_fields':[field('version_2',0),field('boot_id',1,4,'uint64'),field('client_id_mailbox_plus_1',5,2,'uint32'),field('sequence_nonzero',7,2,'uint32'),field('slot',9),field('binding_version',10,2,'uint32'),field('kind_1_action',12),field('south_address_699',13),field('payload_count',14),field('payload_and_zero_padding',15,32),field('reserved_zero',47,16),field('commit_0xA55A',63)],
 'command_result_fields':[field('state',0),field('error_present_0_or_1',1),field('client_id',2,2,'uint32'),field('sequence',4,2,'uint32'),field('slot',6),field('binding_version',7,2,'uint32'),field('accepted_utc_ms',9,4,'uint64'),field('updated_utc_ms',13,4,'uint64'),field('readback_count',17),field('readback_HR698_IR51_IR52',18,3),field('reserved',21,43)],
 'command_states':dict(idle=0,accepted=1,running=2,write_acknowledged=3,readback_confirmed=4,failed=5,uncertain=6,canceled=7)
}
for k,v in defaults.items(): s.setdefault(k,v)
regions=s['regions']; used=set()
for r in regions:
    addresses=set(range(r['base'],r['base']+r['stride']*r['count']))
    assert not used.intersection(addresses) and max(addresses)<65536
    used.update(addresses)
for key,width in [('device_fields',64),('port_fields',32),('summary_fields',24),('detail_fields',144),('group_metadata_fields',12),('parameter_fields',48),('command_fields',64),('command_result_fields',64),('batch_measurement_fields',3),('batch_status_fields',3)]:
    used=set()
    for f in s[key]:
        a=set(range(f['offset'],f['offset']+f['words']))
        assert a and max(a)<width and not used.intersection(a), (key,f)
        used.update(a)
    assert len(used)==width,key
(root/'protocols/north-v2.json').write_text(json.dumps(s,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
camel=lambda name: ''.join(x[:1].upper()+x[1:] for x in name.split('_'))
code=['// Code generated by tools/generate_map.py; DO NOT EDIT.','package protocols','const (']
code += ['MapVersion = 2', 'Capacity = 32', 'MaxPerSouthPort = 8']
for r in regions:
    for k in ['base','stride','count']: code.append(f"{camel(r['name'])}{camel(k)} = {r[k]}")
for f in s['summary_fields']: code.append(f"Summary{camel(f['name'])} = {f['offset']}")
code+=[')','']
(root/'protocols/layout_generated.go').write_text('\n'.join(code),encoding='utf-8')
from point_map_notes_zh import build_document
(root/'docs/09_北向寄存器点表V2.md').write_text(build_document(s),encoding='utf-8')
print('Generated V2 point map, Chinese reference and Go constants')
